class Solution:
    def maxDistance(self, moves: str) -> int:
        x = 0
        y = 0
        wildCards = 0

        for move in moves:
            if move == 'U':
                y += 1
            elif move == 'D':
                y -= 1
            elif move == 'R':
                x += 1
            elif move == 'L':
                x -= 1
            else:
                wildCards += 1

        return abs(x) + abs(y) + wildCards
